#!/usr/bin/env bash
set -Eeuo pipefail

cd "$HOME/Downloads"

F="$HOME/Downloads/build-install-openmw51-global-interior-topology.sh"
CTR="${TSP_BUILDER:-openmw_builder}"
STAMP="$(date +%Y%m%d-%H%M%S)"
BACK="$F.before-worldspace-casemap-$STAMP"
RUNLOG="$HOME/Downloads/global-topology-worldspace-$STAMP.txt"

EXPECTED_MAIN_SHA="87fc1d10096a4469b71bec4eb8c79bc2d0eaa87cc3ef6b3625ab6a33f910032e"
EXPECTED_TOOL_SHA="eac7e0e01ed7507ee32da113c46f36511dd8a3f1f56aa1b684545924b1083229"

test -s "$F" || {
    echo "ERROR: $F not found"
    exit 1
}

echo "===== VERIFY CLEAN CURRENT SOURCE ====="

MAIN_SHA="$(
    docker exec "$CTR"       sha256sum /root/openmw-0.51-tsp-src/apps/navmeshtool/main.cpp |
    awk '{print $1}'
)"

TOOL_SHA="$(
    docker exec "$CTR"       sha256sum /root/openmw-0.51-tsp-build/openmw-navmeshtool |
    awk '{print $1}'
)"

echo "main.cpp: $MAIN_SHA"
echo "navtool:   $TOOL_SHA"

[ "$MAIN_SHA" = "$EXPECTED_MAIN_SHA" ] || {
    echo "ERROR: main.cpp is not the exact source we scanned."
    echo "Nothing changed."
    exit 2
}

[ "$TOOL_SHA" = "$EXPECTED_TOOL_SHA" ] || {
    echo "ERROR: normal navmeshtool is not the known-good build."
    echo "Nothing changed."
    exit 3
}

cp -p "$F" "$BACK"

python3 - "$F" <<'PY_EDIT'
from pathlib import Path
import base64
import sys

p = Path(sys.argv[1])
s = p.read_text(encoding="utf-8")

STEP2 = base64.b64decode(
    ""
).decode()

PATCHER = base64.b64decode(
    ""
).decode()

SELFTEST = base64.b64decode(
    ""
).decode()

# ---------------------------------------------------------------
# Replace Step 2 as one semantic unit.
# Supports the old canonical-only block and a previously patched block.
# ---------------------------------------------------------------
start_marker = 'scp -q "$DEV:$INTERIORMAP" "$OUT/interiormap.lua"\n'
a = s.find(start_marker)

if a < 0:
    raise SystemExit("ERROR: Step 2 start marker not found")

old_end = 'echo "Interior allowlist: $ALLOW_COUNT"\n'
new_end = 'echo "Interior topology targets: $ALLOW_COUNT"\n'

b_old = s.find(old_end, a)
b_new = s.find(new_end, a)

if b_old >= 0 and (b_new < 0 or b_old < b_new):
    b = b_old + len(old_end)
elif b_new >= 0:
    b = b_new + len(new_end)
else:
    raise SystemExit("ERROR: Step 2 end marker not found")

s = s[:a] + STEP2 + s[b:]

# ---------------------------------------------------------------
# Replace the ENTIRE embedded source patcher.
# This removes every stale swim/status exact-anchor variant at once.
# ---------------------------------------------------------------
open_marker = 'cat > "$OUT/patch_topology_exporter.py" <<\'PY_PATCH\'\n'
a = s.find(open_marker)

if a < 0:
    raise SystemExit("ERROR: PY_PATCH opening marker not found")

body = a + len(open_marker)
end = s.find("\nPY_PATCH\n", body)

if end < 0:
    raise SystemExit("ERROR: PY_PATCH closing marker not found")

s = s[:body] + PATCHER + s[end:]

# ---------------------------------------------------------------
# Replace/add the pre-build self-test as one unit.
# ---------------------------------------------------------------
self_heading = 'echo "===== 3B/10 SELF-TEST CURRENT SOURCE COPY ====="\n'
build_heading = 'echo "===== 4/10 BUILD ISOLATED AARCH64 EXPORTER ====="\n'

existing = s.find(self_heading)
build = s.find(build_heading)

if build < 0:
    raise SystemExit("ERROR: build heading not found")

if existing >= 0:
    # Include the preceding blank echo when possible.
    begin = s.rfind("echo\n", 0, existing)
    if begin < 0:
        begin = existing
    s = s[:begin] + SELFTEST + s[build:]
else:
    needle = 'python3 -m py_compile "$OUT/patch_topology_exporter.py"\n'
    pos = s.find(needle)
    if pos < 0:
        raise SystemExit("ERROR: embedded patcher py_compile marker missing")
    pos += len(needle)
    s = s[:pos] + SELFTEST + s[pos:]

# Strong controller-level verification before writing.
required = [
    "TSP_NAVMESH_TOPOLOGY_DB_EXPORT_V2_CASEMAP",
    "matched interiors :",
    "DB worldspaces    :",
    "exact stored key -> canonical V20 cell name",
    "===== 3B/10 SELF-TEST CURRENT SOURCE COPY =====",
]

for token in required:
    if token not in s:
        raise SystemExit("ERROR: patched controller missing " + repr(token))

if "swim_anchor =" in s or "status_anchor =" in s:
    raise SystemExit(
        "ERROR: stale brittle source-anchor code survived replacement"
    )

p.write_text(s, encoding="utf-8", newline="\n")

print("PASS: existing controller patched in place.")
PY_EDIT

echo
echo "===== VERIFY PATCHED CONTROLLER ====="

bash -n "$F"

python3 - "$F" <<'PY_VERIFY'
from pathlib import Path
import sys

s = Path(sys.argv[1]).read_text(encoding="utf-8")

open_marker = 'cat > "$OUT/patch_topology_exporter.py" <<\'PY_PATCH\'\n'
a = s.index(open_marker) + len(open_marker)
b = s.index("\nPY_PATCH\n", a)

payload = s[a:b]
compile(payload, "embedded_topology_exporter_patcher.py", "exec")

assert "TSP_NAVMESH_TOPOLOGY_DB_EXPORT_V2_CASEMAP" in payload
assert "status_re = re.compile" in payload
assert "db_re = re.compile" in payload
assert "swim_anchor =" not in payload
assert "status_anchor =" not in payload

print("PASS: shell syntax.")
print("PASS: embedded Python patcher syntax.")
print("PASS: semantic source anchors installed.")
print("PASS: case-aware DB->canonical mapping installed.")
PY_VERIFY

echo
echo "Backup:"
echo "  $BACK"

echo
echo "===== RUN WHOLE-INTERIOR TOPOLOGY CONTROLLER ====="

set +e
"$F" 2>&1 | tee "$RUNLOG"
RC=${PIPESTATUS[0]}
set -e

echo
echo "===================================================================="
echo "CONTROLLER EXIT CODE: $RC"
echo "Full run log:"
echo "  $RUNLOG"
echo "===================================================================="

if [ "$RC" -ne 0 ]; then
    echo
    echo "===== FAILURE TAIL ====="
    tail -220 "$RUNLOG" || true
fi

exit "$RC"
